previewCss:
.darma-loader-darma-b12-typewriter-carriage { --accent: var(--loader-color, #475569); --accent-2: var(--loader-secondary-color, #ef4444); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .66); position: relative; }
.darma-loader-darma-b12-typewriter-carriage .darma-loader-darma-b12-typewriter-carriage__paper { position: absolute; z-index: 2; top: 0; left: 13%; width: 74%; height: 58%; background: #f8fafc; border-radius: 3px; box-shadow: 0 2px 6px rgba(15, 23, 42, .18); overflow: hidden; }
.darma-loader-darma-b12-typewriter-carriage .darma-loader-darma-b12-typewriter-carriage__paper span { position: absolute; left: 10%; top: 34%; height: 9%; width: 0; border-radius: 2px; background: var(--accent-2); animation: darma-loader-darma-b12-typewriter-carriage-type calc(var(--loader-speed, 1s) * 2.6) steps(12, end) infinite; }
.darma-loader-darma-b12-typewriter-carriage::after { content: ''; position: absolute; z-index: 1; bottom: 0; left: 0; width: 100%; height: 34%; border-radius: 8px 8px 12px 12px; background: linear-gradient(var(--accent), var(--accent-2)); }
.darma-loader-darma-b12-typewriter-carriage::before { content: ''; position: absolute; z-index: 3; bottom: 30%; left: 12%; width: 16%; height: 10%; border-radius: 2px; background: #1e293b; animation: darma-loader-darma-b12-typewriter-carriage-carriage calc(var(--loader-speed, 1s) * 2.6) steps(12, end) infinite; }
@keyframes darma-loader-darma-b12-typewriter-carriage-type { 0% { width: 0; } 62% { width: 66%; } 78% { width: 66%; } 100% { width: 0; } }
@keyframes darma-loader-darma-b12-typewriter-carriage-carriage { 0% { transform: translateX(0); } 62% { transform: translateX(calc(var(--loader-size, 112px) * .48)); } 78% { transform: translateX(calc(var(--loader-size, 112px) * .48)); } 100% { transform: translateX(0); } }

